def sort(a):
    """Hoare 双指针分区,递归。取中间元素为 pivot,左右相向扫描。"""
    a = list(a)
    def quick(lo, hi):
        if lo >= hi:
            return
        pivot = a[(lo + hi) // 2]
        i, j = lo - 1, hi + 1
        while True:
            i += 1
            while a[i] < pivot:
                i += 1
            j -= 1
            while a[j] > pivot:
                j -= 1
            if i >= j:
                break
            a[i], a[j] = a[j], a[i]
        quick(lo, j)            # 注意:Hoare 返回的 j 不一定是 pivot 落点
        quick(j + 1, hi)
    quick(0, len(a) - 1)
    return a

def sort(a):
    """三路快排(荷兰国旗):把数组分成 <pivot / =pivot / >pivot 三段,
    大量重复元素时把相等元素一次性归位,避免退化。"""
    a = list(a)
    def quick(lo, hi):
        if lo >= hi:
            return
        pivot = a[lo]
        lt, i, gt = lo, lo + 1, hi   # [lo,lt) <pivot, [lt,i) =pivot, (gt,hi] >pivot
        while i <= gt:
            if a[i] < pivot:
                a[lt], a[i] = a[i], a[lt]
                lt += 1
                i += 1
            elif a[i] > pivot:
                a[i], a[gt] = a[gt], a[i]
                gt -= 1
            else:
                i += 1
        quick(lo, lt - 1)
        quick(gt + 1, hi)
    quick(0, len(a) - 1)
    return a
